#ifdef GL_ES
precision mediump float;
#endif



//-------------------------------------------------------------
// Inverse stereographic projection: maps a point p in ℝ³ to S³.
// p is a vec3; output is a vec4 on S³ given by
//    q = ((1 - |p|²)/(1+|p|²), 2p/(1+|p|²))
vec4 liftToS3(vec3 p) {
    float d2 = dot(p, p);
    float denom = 1.0 + d2;
    return vec4((1.0 - d2) / denom, (2.0 * p) / denom);
}

//-------------------------------------------------------------
// Animated group action: We animate by applying a rotation to q ∈ S³.
// Here we choose a rotation axis along the diagonal (1,1,1) and define
// the rotation quaternion as
//   q_anim = (cos(iTime/2), sin(iTime/2) * (1,1,1)/√3)
// so that when iTime goes from 0 to 4π the underlying SO(3) rotation completes one full cycle.
vec4 animateS3(vec4 q) {
    vec3 axis = normalize(vec3(1.0, 1.0, 1.0));
    float halfAngle = iTime / 2.0;
    vec4 q_anim = vec4(cos(halfAngle), sin(halfAngle) * axis);
    // Quaternion multiplication: left–multiply by q_anim.
    // We'll implement a simple quaternion multiplication:
    float a1 = q_anim.x, b1 = q_anim.y, c1 = q_anim.z, d1 = q_anim.w;
    float a2 = q.x,      b2 = q.y,      c2 = q.z,      d2 = q.w;
    return vec4(
      a1*a2 - b1*b2 - c1*c2 - d1*d2,
      a1*b2 + b1*a2 + c1*d2 - d1*c2,
      a1*c2 - b1*d2 + c1*a2 + d1*b2,
      a1*d2 + b1*c2 - c1*b2 + d1*a2
    );
}

//-------------------------------------------------------------
// Hopf fibration: We interpret a point on S³ (a quaternion q = (a,b,c,d))
// as a pair of complex numbers (z, w) where z = a + i·b and w = c + i·d.
// One useful Hopf map is to compute:
vec2 hopfBase(vec4 q) {
    // Compute intermediary coordinates:
    float X = 2.0 * (q.x * q.z + q.y * q.w);
    float Y = 2.0 * (q.y * q.z - q.x * q.w);
    float Z = q.x*q.x + q.y*q.y - q.z*q.z - q.w*q.w;
    // Stereographic projection from S² (X,Y,Z) to ℂ:
    return (1.0 / (1.0 + Z + 0.001)) * vec2(X, Y);
}

// Compute the fiber phase from q by interpreting it as (z, w) ∈ ℂ²
// and defining the fiber angle as psi = arg(z) - arg(w).
float fiberPhase(vec4 q) {
    float phi_z = atan(q.y, q.x); // arg(z) for z = (a, b)
    float phi_w = atan(q.w, q.z); // arg(w) for w = (c, d)
    float psi = phi_z - phi_w;
    if(psi > 3.14159) psi -= 2.0 * 3.14159;
    if(psi < -3.14159) psi += 2.0 * 3.14159;
    return psi;
}

//-------------------------------------------------------------
// Complex iteration on the base: iterate f(z) = α·z² + c,
// where z ∈ ℝ² represents a complex number.
vec2 iterateComplex(vec2 z0, vec2 c, out float iterCount) {
    vec2 z = z0;
    const int maxIter = 50;
    int i;
    for(i = 0; i < maxIter; i++){
        if(dot(z, z) > 4.0) break;
        // Complex square: (x,y)² = (x*x - y*y, 2*x*y)
        z = vec2(z.x*z.x - z.y*z.y, 2.0*z.x*z.y);
        z += c;
    }
    iterCount = float(i);
    return z;
}

//-------------------------------------------------------------
// Color mapping: uses the normalized iteration count and fiber phase.
// fiberNorm is the fiber phase normalized from [-π, π] to [0, 1].
vec3 getColor(float t, float fiberNorm) {
    vec3 colBase = mix(vec3(0.2, 0.4, 0.8), vec3(1.0, 0.9, 0.3), t);
    float mod = 0.5 + 0.5 * cos(6.2831 * fiberNorm);
    return colBase * mod;
}

//-------------------------------------------------------------
// mainImage: For each pixel, we:
// 1. Compute a 3D point p from screen coordinates.
// 2. Lift p to S³ via inverse stereographic projection.
// 3. Apply an animated rotation (group action) that exhibits the double–cover effect.
// 4. Compute the Hopf base coordinate and fiber phase.
// 5. Iterate a complex quadratic map on the base.
// 6. Color the pixel based on iteration count and fiber phase.
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalize screen coordinates (centered, aspect–corrected)
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    // Create a 3D point from uv: here we set p = (uv, k)
    float k = 0.3; // Lifts the screen into 3D
    vec3 p = vec3(uv, k);

    // Lift p to S³ using inverse stereographic projection.
    vec4 q = liftToS3(p);

    // Apply the animated group action to q.
    q = animateS3(q);

    // Compute the Hopf base coordinate and fiber phase.
    vec2 zBase = hopfBase(q);
    float psi = fiberPhase(q);
    // Normalize fiber phase from [-π, π] to [0, 1]
    float fiberNorm = (psi + 3.14159) / (2.0 * 3.14159);

    // Complex iteration on the base.
    // Use a scaling factor α = 1.0 and constant cConst.
    vec2 cConst = vec2(0.3, 0.0);
    float iter;
    vec2 zFinal = iterateComplex(zBase, cConst, iter);
    float t = iter / 50.0;

    // Final color: combine the base iteration color with the fiber modulation.
    vec3 color = getColor(t, fiberNorm);

    fragColor = vec4(color, 1.0);
}
